using Microsoft.EntityFrameworkCore;
using UNOPS.PAO.Domain.Entities;
using UNOPS.PAO.Domain.Enums;
using UNOPS.PAO.UNOPSDataAccess.Context;

namespace UNOPS.PAO.UNOPSDataAccess.Seed.Seeders;

/// <summary>
/// Seeds UNCF Indicators (UN Cooperation Framework Indicators) with proper insert/update logic
/// Data synced from External Data Service (ERP Database)
/// </summary>
public static class UNCFIndicatorSeeder
{
    public static async Task SeedUNCFIndicatorsAsync(UNOPSAppDbContext context)
    {
        Console.WriteLine("🔄 Seeding UNCF Indicators...");

        var indicatorsToSeed = GetUNCFIndicatorsToSeed();

        // Get existing UNCF Indicators from database
        var existingIndicators = await context.Set<UNCFIndicator>().ToListAsync();

        // Track indicator identifiers to keep
        var indicatorKeysToKeep = indicatorsToSeed
            .Select(i => i.UNCFIndicatorId)
            .ToHashSet();

        // Insert or Update UNCF Indicators
        foreach (var indicatorData in indicatorsToSeed)
        {
            var existingIndicator = existingIndicators.FirstOrDefault(i =>
                i.UNCFIndicatorId == indicatorData.UNCFIndicatorId);

            if (existingIndicator == null)
            {
                // Insert new UNCF Indicator
                context.Set<UNCFIndicator>().Add(indicatorData);
                Console.WriteLine($"  ✅ Inserted UNCF Indicator: {indicatorData.UNCFIndicatorId} - {indicatorData.Country}");
            }
            else
            {
                // Update if any properties changed
                bool hasChanges = false;

                if (existingIndicator.Name != indicatorData.Name)
                {
                    existingIndicator.Name = indicatorData.Name;
                    hasChanges = true;
                }

                if (existingIndicator.Unit != indicatorData.Unit)
                {
                    existingIndicator.Unit = indicatorData.Unit;
                    hasChanges = true;
                }

                if (existingIndicator.Description != indicatorData.Description)
                {
                    existingIndicator.Description = indicatorData.Description;
                    hasChanges = true;
                }

                if (existingIndicator.Indicators != indicatorData.Indicators)
                {
                    existingIndicator.Indicators = indicatorData.Indicators;
                    hasChanges = true;
                }

                if (existingIndicator.Baseline != indicatorData.Baseline)
                {
                    existingIndicator.Baseline = indicatorData.Baseline;
                    hasChanges = true;
                }

                if (existingIndicator.Narrative != indicatorData.Narrative)
                {
                    existingIndicator.Narrative = indicatorData.Narrative;
                    hasChanges = true;
                }

                if (existingIndicator.Country != indicatorData.Country)
                {
                    existingIndicator.Country = indicatorData.Country;
                    hasChanges = true;
                }

                if (existingIndicator.UNCFOutcomeExternalId != indicatorData.UNCFOutcomeExternalId)
                {
                    existingIndicator.UNCFOutcomeExternalId = indicatorData.UNCFOutcomeExternalId;
                    hasChanges = true;
                }

                if (existingIndicator.UNCFIndicatorStartDate != indicatorData.UNCFIndicatorStartDate)
                {
                    existingIndicator.UNCFIndicatorStartDate = indicatorData.UNCFIndicatorStartDate;
                    hasChanges = true;
                }

                if (existingIndicator.UNCFIndicatorEndDate != indicatorData.UNCFIndicatorEndDate)
                {
                    existingIndicator.UNCFIndicatorEndDate = indicatorData.UNCFIndicatorEndDate;
                    hasChanges = true;
                }

                if (existingIndicator.UNCFIndicatorLastUpdatedDate != indicatorData.UNCFIndicatorLastUpdatedDate)
                {
                    existingIndicator.UNCFIndicatorLastUpdatedDate = indicatorData.UNCFIndicatorLastUpdatedDate;
                    hasChanges = true;
                }

                if (existingIndicator.Status != indicatorData.Status)
                {
                    existingIndicator.Status = indicatorData.Status;
                    hasChanges = true;
                }

                if (existingIndicator.IsDeleted)
                {
                    existingIndicator.IsDeleted = false;
                    hasChanges = true;
                }

                if (hasChanges)
                {
                    Console.WriteLine($"  🔄 Updated UNCF Indicator: {indicatorData.UNCFIndicatorId} - {indicatorData.Country}");
                }
                else
                {
                    Console.WriteLine($"  ⏭️  Skipped UNCF Indicator (unchanged): {indicatorData.UNCFIndicatorId} - {indicatorData.Country}");
                }
            }
        }

        await context.SaveChangesAsync();
        Console.WriteLine($"✅ UNCF Indicators seeding completed - Total: {indicatorsToSeed.Count}\n");
    }

