            new UNCFIndicator
            {
                Name = "Robust system in place for identifying, mapping and prioritizing vulnerable populations for assistance during a disaster",
                Status = EntityStatus.Active,
                IsDeleted = false,
                UNCFIndicatorId = "212",
                Unit = null,
                Description = "2019 Indicator: Bhutan has capacity to independently identify, map and prioritize vulnerable populations within 72 hours of a disaster",
